                      data-testid={`button-restore-${backup.id}`}
                    >
                      <RotateCcw className="w-4 h-4" />
                    </Button>
                  )}

                  <Button
                    size="icon"
                    variant="ghost"
                    onClick={() => deleteMutation.mutate(backup.id)}
                    disabled={deleteMutation.isPending}
