}

function RequestsStatsModal({
  requestsData,
  requestsLoading,
  onClose,
}: {
  requestsData: any;
  requestsLoading: boolean;
  onClose: () => void;
}) {
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
