import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { queryClient } from "@/lib/queryClient";
import { ExternalLink, Trash2, Upload, X } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function OwnerImagesPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [previewUrls, setPreviewUrls] = useState<string[]>([]);

  /* ==========================================================
     1) التحقق من الجلسة
  ============================================================*/
  const { data: sessionData, isLoading: sessionLoading } = useQuery<any>({
    queryKey: ["/api/owner/session"],
  });

  useEffect(() => {
    if (!sessionLoading && !sessionData?.isLoggedIn) {
      setLocation("/owner/login");
    }
  }, [sessionLoading, sessionData, setLocation]);

  /* ==========================================================
     2) جلب صور R2 مباشرة
  ============================================================*/
  const { data: r2Data, isLoading: r2Loading } = useQuery({
    queryKey: ["/api/owner/r2-images"],
    queryFn: async () => {
      const res = await fetch("/api/owner/r2-images", {
        credentials: "include",
      });
      if (!res.ok) throw new Error("Failed to load images");
      return res.json();
    },
  });

  const r2Images = r2Data?.images || [];

  /* ==========================================================
     3) رفع الصور
  ============================================================*/
  const uploadMutation = useMutation({
    mutationFn: async (files: File[]) => {
      const formData = new FormData();
      files.forEach((f) => {
        formData.append("images", f);
      });

      const res = await fetch("/api/owner/images", {
        method: "POST",
        body: formData,
        credentials: "include",
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || `HTTP ${res.status}`);
      }

      return data;
    },
    onSuccess: (data) => {
      if (data.urls && r2Images) {
        // إضافة الصور المرفوعة مباشرة
        const newImages = [...r2Images, ...data.urls];
        queryClient.setQueryData(["/api/owner/r2-images"], {
          images: newImages
        });
      }

      setSelectedFiles([]);
      setPreviewUrls([]);
      toast({ 
        title: "نجح!", 
        description: `تم رفع ${data.count} صورة بنجاح` 
      });
    },
    onError: (err: any) => {
      toast({ 
        title: "خطأ في الرفع", 
        description: err?.message || "فشل الرفع",
        variant: "destructive" 
      });
    },
  });

  const handleSelectFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);

    if (r2Images.length + files.length > 15) {
      toast({
        title: "تجاوز الحد",
        description: `الحد الأقصى 15 صورة`,
        variant: "destructive",
      });
      return;
    }

    setSelectedFiles(files);
    setPreviewUrls(files.map((f) => URL.createObjectURL(f)));
  };

  /* ==========================================================
     4) حذف صورة (المسار الصحيح DELETE /api/owner/images/:index)
  ============================================================*/
  const deleteMutation = useMutation({
    mutationFn: async (url: string) => {
      const res = await fetch(`/api/owner/images/delete`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }),
      });

      if (!res.ok) throw new Error(await res.text());
      return res.json();
    },
    onSuccess: () => {
      // إزالة الصورة من الـ cache مباشرة
      const currentData = queryClient.getQueryData<{images: string[]}>(["/api/owner/r2-images"]);
      if (currentData) {
        const updatedImages = currentData.images.filter(img => img !== deleteMutation.variables);
        queryClient.setQueryData(["/api/owner/r2-images"], {
          images: updatedImages
        });
      }
      toast({ title: "تم حذف الصورة بنجاح" });
    },
    onError: (err: any) => {
      toast({
        title: "خطأ",
        description: err.message,
        variant: "destructive",
      });
    },
  });

  // حذف الصورة باستخدام الـ URL الكامل
  const handleDelete = (url: string) => {
    if (!confirm("هل تريد حذف هذه الصورة؟")) return;

    // إرسال URL الكامل للحذف
    deleteMutation.mutate(url);
  };

  /* ==========================================================
     واجهة الصفحة
  ============================================================*/
  if (sessionLoading || r2Loading)
    return <div className="p-6 text-center">جاري التحميل…</div>;

  return (
    <div className="min-h-screen bg-background p-6">
      <div className="max-w-4xl mx-auto space-y-6">
        <h1 className="text-3xl font-bold text-[#4a3b2a]">إدارة الصور</h1>

        {/* ========== الصور الحالية ========== */}
        <Card className="p-6">
          <h2 className="text-xl font-bold mb-4">
            الصور الحالية ({r2Images.length}/15)
          </h2>

          {r2Images.length > 0 ? (
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {r2Images.map((url: string, i: number) => (
                <div key={i} className="relative group">
                  <img
                    src={url}
                    className="w-full h-48 object-cover rounded-lg"
                  />

                  <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-3 rounded-lg transition">
                    <a
                      href={url}
                      target="_blank"
                      className="p-2 bg-blue-500 text-white rounded-full"
                    >
                      <ExternalLink />
                    </a>

                    <button
                      className="p-2 bg-red-500 text-white rounded-full"
                      onClick={() => handleDelete(url)}
                    >
                      <Trash2 />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="py-10 text-center text-muted-foreground">
              لا توجد صور مرفوعة
            </div>
          )}
        </Card>

        {/* ========== رفع صور جديدة ========== */}
        <Card className="p-6">
          <h2 className="text-xl font-bold mb-4">رفع صور جديدة</h2>

          <div className="border-2 border-dashed p-8 text-center rounded-lg">
            <Upload className="w-12 h-12 mx-auto mb-3 text-[#b88d2b]" />

            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept="image/*"
              className="hidden"
              onChange={handleSelectFiles}
            />

            <Button
              className="bg-[#b88d2b]"
              onClick={() => fileInputRef.current?.click()}
            >
              اختر الصور
            </Button>
          </div>

          {previewUrls.length > 0 && (
            <>
              <h3 className="mt-4 font-semibold">
                الصور المختارة ({previewUrls.length})
              </h3>

              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mt-2">
                {previewUrls.map((url, i) => (
                  <div key={i} className="relative">
                    <img
                      src={url}
                      className="w-full h-48 object-cover rounded-lg"
                    />
                    <button
                      className="absolute top-2 right-2 bg-red-500 text-white rounded-full p-1"
                      onClick={() => {
                        URL.revokeObjectURL(url);
                        setPreviewUrls((p) => p.filter((_, x) => x !== i));
                        setSelectedFiles((p) => p.filter((_, x) => x !== i));
                      }}
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>

              <Button
                className="w-full mt-4 bg-[#b88d2b]"
                onClick={() => uploadMutation.mutate(selectedFiles)}
              >
                رفع {selectedFiles.length} صورة
              </Button>
            </>
          )}
        </Card>
      </div>
    </div>
  );
}

files.client/src/pages/owner-login.tsx:
import { useState } from "react";
import { useLocation } from "wouter";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Home, Lock } from "lucide-react";

export default function OwnerLogin() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [mode, setMode] = useState<"owner" | "admin">("owner");

  // Owner fields
  const [propertyNumber, setPropertyNumber] = useState("");
  const [pin, setPin] = useState("");

  // Admin fields
  const [adminCode, setAdminCode] = useState("");
  const [adminPassword, setAdminPassword] = useState("");

  const [isLoading, setIsLoading] = useState(false);

  const handleOwnerLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!propertyNumber || !pin) {
      toast({
        title: "خطأ",
        description: "الرجاء إدخال رقم العقار والرقم السري",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch("/api/owner/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ propertyNumber, pin }),
      });

      const data = await response.json();

      if (!response.ok) {
        toast({
          title: "فشل تسجيل الدخول",
          description: data.error || "رقم العقار أو الرقم السري غير صحيح",
          variant: "destructive",
        });
        setIsLoading(false);
        return;
      }

      toast({
        title: "تم تسجيل الدخول",
        description: "مرحباً بك في لوحة التحكم",
      });

      window.location.href = "/owner/dashboard";
    } catch (error) {
      console.error("Login error:", error);
      toast({
        title: "خطأ غير متوقع",
        description: "تعذر الاتصال بالخادم",
        variant: "destructive",
      });
      setIsLoading(false);
    }
  };

  const handleAdminLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!adminCode || !adminPassword) {
      toast({
        title: "خطأ",
        description: "الرجاء إدخال كود الأدمن وكلمة المرور",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch("/api/admin/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ code: adminCode, password: adminPassword }),
      });

      const data = await response.json();

      if (!response.ok) {
        toast({
          title: "فشل تسجيل الدخول",
          description: data.error || "كود الأدمن أو كلمة المرور غير صحيحة",
          variant: "destructive",
        });
        setIsLoading(false);
        return;
      }

      toast({
        title: "تم تسجيل الدخول",
        description: "مرحباً بك في لوحة الإدارة",
      });

      window.location.href = "/admin";
    } catch (error) {
      console.error("Admin login error:", error);
      toast({
        title: "خطأ غير متوقع",
        description: "تعذر الاتصال بالخادم",
        variant: "destructive",
      });
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <Card className="w-full max-w-md p-8">
        <div className="text-center mb-8">
          <div className="flex justify-center mb-4">
            <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
              <Home className="w-8 h-8 text-primary" />
            </div>
          </div>
          <h1 className="text-2xl font-bold text-primary mb-2" data-testid="text-login-title">
            مودي الذكي
          </h1>
          <p className="text-muted-foreground">تسجيل دخول آمن</p>
        </div>

        <Tabs value={mode} onValueChange={(v) => setMode(v as "owner" | "admin")} className="w-full">
          <TabsList className="grid w-full grid-cols-2 mb-6">
            <TabsTrigger value="owner" className="gap-2">
              <Home className="w-4 h-4" />
              <span className="hidden sm:inline">صاحب العقار</span>
              <span className="sm:hidden">ملاك</span>
            </TabsTrigger>
            <TabsTrigger value="admin" className="gap-2">
              <Lock className="w-4 h-4" />
              <span className="hidden sm:inline">المسؤول</span>
              <span className="sm:hidden">أدمن</span>
            </TabsTrigger>
          </TabsList>

          {/* Owner Login Tab */}
          <TabsContent value="owner">
            <form onSubmit={handleOwnerLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-semibold mb-2">رقم العقار</label>
                <Input
                  type="text"
                  placeholder="00123"
                  value={propertyNumber}
                  onChange={(e) => setPropertyNumber(e.target.value)}
                  disabled={isLoading}
                  data-testid="input-property-number"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2">الرقم السري</label>
                <Input
                  type="password"
                  placeholder="••••••"
                  value={pin}
                  onChange={(e) => setPin(e.target.value)}
                  disabled={isLoading}
                  data-testid="input-pin"
                />
              </div>

              <Button
                type="submit"
                className="w-full gradient-golden"
                disabled={isLoading}
                data-testid="button-login"
              >
                {isLoading ? "جاري تسجيل الدخول..." : "تسجيل الدخول"}
              </Button>
            </form>

            <div className="mt-6 text-center text-sm text-muted-foreground">
              <p>ليس لديك حساب؟</p>
              <Button
                variant="link"
                onClick={() => setLocation("/subscription")}
                className="text-primary"
                data-testid="link-register"
              >
                سجل معنا الآن
              </Button>
            </div>
          </TabsContent>

          {/* Admin Login Tab */}
          <TabsContent value="admin">
            <form onSubmit={handleAdminLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-semibold mb-2">كود المسؤول</label>
                <Input
                  type="text"
                  placeholder="أدخل كود المسؤول"
                  value={adminCode}
                  onChange={(e) => setAdminCode(e.target.value)}
                  disabled={isLoading}
                  data-testid="input-admin-code"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2">كلمة المرور</label>
                <Input
                  type="password"
                  placeholder="••••••"
                  value={adminPassword}
                  onChange={(e) => setAdminPassword(e.target.value)}
                  disabled={isLoading}
                  data-testid="input-admin-password"
                />
              </div>

              <Button
                type="submit"
                className="w-full gradient-golden"
                disabled={isLoading}
                data-testid="button-admin-login"
              >
                {isLoading ? "جاري تسجيل الدخول..." : "تسجيل الدخول"}
              </Button>
            </form>
          </TabsContent>
        </Tabs>
      </Card>
    </div>
  );
}

files.client/src/pages/owner-subscription.tsx:
import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Property, Package, Subscription } from "@shared/schema";
import { CalendarDays, Crown, TrendingUp, Check, ExternalLink, Upload } from "lucide-react";

export default function OwnerSubscriptionPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedAction, setSelectedAction] = useState<'extend' | 'upgrade' | null>(null);
  const [selectedPackageId, setSelectedPackageId] = useState<string | null>(null);
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState<'online' | 'bank' | null>(null);
  const [paymentInfo, setPaymentInfo] = useState<any>(null);
  const [receiptFile, setReceiptFile] = useState<File | null>(null);
  const [isSubmittingPayment, setIsSubmittingPayment] = useState(false);

  // جلب بيانات المالك
  const { data: property } = useQuery<Property>({
    queryKey: ["/api/owner/property"],
  });

  // جلب الاشتراك الحالي
  const { data: currentSubscription } = useQuery<Subscription>({
    queryKey: ["/api/owner/current-subscription"],
  });

  // جلب جميع الباقات
  const { data: packages = [] } = useQuery<Package[]>({
    queryKey: ["/api/packages"],
  });

  // جلب الباقة الحالية
  const currentPackage = packages.find(p => p.id === currentSubscription?.packageId);

  // حساب الأيام المتبقية
  const daysRemaining = currentSubscription
    ? Math.ceil((new Date(currentSubscription.endDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))
    : 0;

  // حساب مدة الاشتراك من البيانات
  const subscriptionDuration = currentSubscription && currentSubscription.startDate && currentSubscription.endDate
    ? Math.ceil((new Date(currentSubscription.endDate).getTime() - new Date(currentSubscription.startDate).getTime()) / (1000 * 60 * 60 * 24))
    : 0;

  const isSubscriptionActive = daysRemaining > 0;

  // تحضير معلومات الدفع
  const prepareMutation = useMutation({
    mutationFn: async ({ action, packageId }: { action: 'extend' | 'upgrade'; packageId: string }) => {
      const response = await apiRequest('POST', '/api/owner/subscription/prepare-payment', {
        action,
        packageId,
      });
      return response.json();
    },
    onSuccess: (data) => {
      setPaymentInfo(data);
    },
    onError: (error: any) => {
      toast({
        title: "❌ خطأ",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // تأكيد الدفع والاشتراك
  const confirmMutation = useMutation({
    mutationFn: async ({ paymentId }: { paymentId: string }) => {
      const response = await apiRequest('POST', '/api/owner/subscription/confirm', {
        action: paymentInfo?.action,
        packageId: paymentInfo?.packageId,
        paymentId,
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/owner/current-subscription"] });
      toast({
        title: "✅ تم بنجاح",
        description: `تم ${paymentInfo?.action === 'extend' ? 'التمديد' : 'الترقية'} بنجاح وتم استقطاع المبلغ`,
      });
      setSelectedAction(null);
      setPaymentInfo(null);
      setSelectedPackageId(null);
      setSelectedPaymentMethod(null);
    },
    onError: (error: any) => {
      toast({
        title: "❌ خطأ",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  if (!property || !currentSubscription) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Card className="p-8 text-center">
          <div className="inline-block w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-lg font-semibold text-foreground">جاري تحميل البيانات...</p>
          <p className="text-sm text-muted-foreground mt-2">يرجى الانتظار قليلاً</p>
        </Card>
      </div>
    );
  }

  const availablePackages = packages.filter(p => {
    if (selectedAction === 'upgrade') {
      return p.price > (currentPackage?.price || 0);
    }
    return true;
  });

  return (
    <div className="min-h-screen bg-background p-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <header className="mb-8 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-[#434040] mb-2">إدارة الاشتراك</h1>
            <p className="text-muted-foreground">عقار: {property.name} ({property.propertyNumber})</p>
          </div>
          <Button
            onClick={() => setLocation("/owner/subscription")}
            variant="outline"
            className="flex items-center gap-2"
            data-testid="button-view-all-packages"
          >
            <span>اشترك معنا</span>
            <ExternalLink className="w-4 h-4" />
          </Button>
        </header>

        {/* الاشتراك الحالي */}
        <Card className={`mb-8 p-6 border-2 transition-all ${
          currentPackage?.type === 'مميز' && isSubscriptionActive
            ? 'border-green-500 bg-gradient-to-r from-green-50 to-background dark:from-green-950/20'
            : 'border-[#e0c97b] bg-gradient-to-r from-[#fffdf0] to-background'
        }`}>
          <div className="flex items-start justify-between mb-6">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Crown className="w-5 h-5 text-[#b88d2b]" />
                <h2 className="text-2xl font-bold text-[#434040]">الباقة الحالية</h2>
              </div>
              <p className="text-lg font-semibold text-[#b88d2b]">{currentPackage?.name || 'بدون اشتراك'}</p>
            </div>
            <div className="flex gap-2 items-center">
              {currentPackage?.type === 'مميز' && isSubscriptionActive && (
                <Badge className="bg-green-500 text-white animate-pulse">
                  ✓ مفعلة
                </Badge>
              )}
              <Badge className={isSubscriptionActive ? "bg-green-500" : "bg-red-500"}>
                {isSubscriptionActive ? '✓ نشط' : '✗ منتهي'}
              </Badge>
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
            <div>
              <p className="text-sm text-muted-foreground">السعر الشهري</p>
              <p className="text-2xl font-bold text-[#434040]">{(currentSubscription as any)?.price || currentPackage?.price || 0} ر.س</p>
            </div>
            <div>
              <p className="text-sm text-muted-foreground">المدة</p>
              <p className="text-2xl font-bold text-[#434040]">{subscriptionDuration || currentPackage?.duration || 0} يوم</p>
            </div>
            <div>
              <p className="text-sm text-muted-foreground">الأيام المتبقية</p>
              <p className={`text-2xl font-bold ${daysRemaining > 0 ? 'text-green-600' : 'text-red-600'}`}>
                {Math.max(0, daysRemaining)} يوم
              </p>
            </div>
            <div>
              <p className="text-sm text-muted-foreground">انتهاء الاشتراك</p>
              <p className="text-lg font-bold text-[#434040]">
                {new Date(currentSubscription.endDate).toLocaleDateString('en-US')}
              </p>
            </div>
          </div>

          {/* أزرار الإجراءات */}
          <div className="flex gap-3 flex-wrap">
            <Button
              onClick={() => setSelectedAction('extend')}
              variant={selectedAction === 'extend' ? 'default' : 'outline'}
              className="flex-1 md:flex-initial"
            >
              <CalendarDays className="w-4 h-4 ml-2" />
              تمديد الاشتراك
            </Button>
            <Button
              onClick={() => setSelectedAction('upgrade')}
              variant={selectedAction === 'upgrade' ? 'default' : 'outline'}
              className="flex-1 md:flex-initial"
            >
              <TrendingUp className="w-4 h-4 ml-2" />
              الترقية إلى باقة أفضل
            </Button>
          </div>
        </Card>

        {/* اختيار الباقة */}
        {selectedAction && (
          <Card className="mb-8 p-6">
            <h3 className="text-xl font-bold mb-6">
              {selectedAction === 'extend' ? 'اختر مدة التمديد' : 'اختر الباقة الجديدة'}
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
              {availablePackages.map(pkg => (
                <div
                  key={pkg.id}
                  onClick={() => setSelectedPackageId(pkg.id)}
                  className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${
                    selectedPackageId === pkg.id
                      ? 'border-[#b88d2b] bg-[#fffdf0]'
                      : 'border-border hover:border-[#b88d2b]'
                  }`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="font-bold text-[#434040]">{pkg.name}</h4>
                    {selectedPackageId === pkg.id && (
                      <Check className="w-5 h-5 text-[#b88d2b]" />
                    )}
                  </div>
                  <p className="text-sm text-muted-foreground mb-3">{pkg.duration} يوم</p>
                  <p className="text-2xl font-bold text-[#b88d2b]">{pkg.price} ر.س</p>
                </div>
              ))}
            </div>

            <div className="flex gap-3">
              <Button
                onClick={() => {
                  if (selectedPackageId && selectedAction) {
                    prepareMutation.mutate({ 
                      action: selectedAction, 
                      packageId: selectedPackageId 
                    });
                  }
                }}
                disabled={!selectedPackageId || prepareMutation.isPending}
                className="flex-1"
              >
                {prepareMutation.isPending ? 'جاري التحضير...' : 'متابعة للدفع'}
              </Button>
              <Button
                onClick={() => setSelectedAction(null)}
                variant="outline"
                className="flex-1"
              >
                إلغاء
              </Button>
            </div>
          </Card>
        )}

        {/* نموذج الدفع */}
        {paymentInfo && (
          <Card className="mb-8 p-6 border-[#b88d2b] bg-[#fffdf0]">
            <h2 className="text-2xl font-bold text-[#434040] mb-6">معلومات الدفع</h2>

            <div className="bg-white p-4 rounded-lg mb-6 border border-[#e0c97b]">
              <div className="flex justify-between mb-3">
                <span className="text-muted-foreground">الباقة:</span>
                <span className="font-bold text-[#434040]">{paymentInfo.packageName}</span>
              </div>
              <div className="flex justify-between mb-3">
                <span className="text-muted-foreground">المدة:</span>
                <span className="font-bold text-[#434040]">{paymentInfo.duration} يوم</span>
              </div>
              <div className="flex justify-between border-t pt-3">
                <span className="text-lg font-bold text-[#434040]">الإجمالي:</span>
                <span className="text-2xl font-bold text-[#b88d2b]">{paymentInfo.price} ر.س</span>
              </div>
            </div>

            <div className="mb-6">
              <h3 className="text-lg font-bold mb-3 text-[#434040]">اختر طريقة الدفع:</h3>
              <div className="space-y-3">
                <div
                  onClick={() => { setSelectedPaymentMethod('online'); setReceiptFile(null); }}
                  className={`p-4 border-2 rounded-lg cursor-pointer transition ${selectedPaymentMethod === 'online' ? 'border-[#434040] bg-[#434040]/5' : 'border-border hover:border-[#434040]/50'}`}
                  data-testid="payment-method-online"
                >
                  <div className="font-semibold">الدفع الإلكتروني</div>
                  <p className="text-sm text-muted-foreground">بطاقة ائتمان أو Apple Pay</p>
                </div>
                <div
                  onClick={() => setSelectedPaymentMethod('bank')}
                  className={`p-4 border-2 rounded-lg cursor-pointer transition ${selectedPaymentMethod === 'bank' ? 'border-[#434040] bg-[#434040]/5' : 'border-border hover:border-[#434040]/50'}`}
                  data-testid="payment-method-bank"
                >
                  <div className="font-semibold">تحويل بنكي</div>
                  <p className="text-sm text-muted-foreground">مع تحميل إيصال التحويل</p>
                </div>
              </div>

              {/* Bank Receipt Upload */}
              {selectedPaymentMethod === 'bank' && (
                <div className="p-4 bg-muted/30 rounded-lg mt-3">
                  <label className="block text-sm font-semibold mb-2">إيصال التحويل</label>
                  <input ref={fileInputRef} type="file" accept="image/*" onChange={(e) => setReceiptFile(e.target.files?.[0] || null)} className="hidden" />
                  <Button type="button" variant="outline" onClick={() => fileInputRef.current?.click()} className="w-full gap-2">
                    <Upload className="w-4 h-4" />
                    {receiptFile ? receiptFile.name : 'اختر صورة الإيصال'}
                  </Button>
                </div>
              )}
            </div>

            <div className="flex gap-3">
              <Button
                onClick={async () => {
                  if (!selectedPaymentMethod) return;
                  setIsSubmittingPayment(true);
                  try {
                    const propertyNumber = property?.propertyNumber;
                    if (selectedPaymentMethod === 'online') {
                      const paymentResponse = await apiRequest('POST', '/api/owner/payment/initiate', {
                        propertyNumber,
                        packageId: paymentInfo.packageId,
                        action: paymentInfo.action,
                        paymentMethod: 'cards',
                      });
                      const paymentData = await paymentResponse.json();
                      if (paymentData.checkoutUrl) {
                        window.location.href = paymentData.checkoutUrl;
                      } else {
                        throw new Error('لم يتم الحصول على رابط الدفع');
                      }
                    } else if (selectedPaymentMethod === 'bank' && receiptFile) {
                      const formData = new FormData();
                      formData.append('propertyNumber', propertyNumber || '');
                      formData.append('packageId', paymentInfo.packageId);
                      formData.append('receipt', receiptFile);
                      formData.append('action', paymentInfo.action);
                      await fetch('/api/owner/payment/bank-transfer', {
                        method: 'POST',
                        body: formData,
                      });
                      toast({
                        title: 'تم استقبال طلبك',
                        description: 'سيتم تفعيل الاشتراك بعد التحقق من التحويل البنكي',
                      });
                      queryClient.invalidateQueries({ queryKey: ['/api/owner/current-subscription'] });
                      setPaymentInfo(null);
                      setSelectedPaymentMethod(null);
                      setReceiptFile(null);
                    }
                  } catch (err: any) {
                    toast({
                      title: 'خطأ في الدفع',
                      description: err.message || 'حدث خطأ غير متوقع',
                      variant: 'destructive',
                    });
                  } finally {
                    setIsSubmittingPayment(false);
                  }
                }}
                disabled={!selectedPaymentMethod || isSubmittingPayment || (selectedPaymentMethod === 'bank' && !receiptFile)}
                className="flex-1"
                data-testid="button-confirm-payment"
              >
                {isSubmittingPayment ? 'جاري الدفع...' : 'تأكيد الدفع'}
              </Button>
              <Button
                onClick={() => {
                  setPaymentInfo(null);
                  setSelectedPaymentMethod(null);
                  setReceiptFile(null);
                }}
                variant="outline"
                className="flex-1"
              >
                إلغاء
              </Button>
            </div>
          </Card>
        )}

        {/* الباقات المتاحة */}
        <div>
          <h3 className="text-xl font-bold mb-6">الباقات المتاحة</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {packages.map(pkg => (
              <Card key={pkg.id} className="p-6 hover:shadow-lg transition-shadow">
                <h4 className="text-lg font-bold mb-4 text-[#434040]">{pkg.name}</h4>
                <div className="mb-4">
                  <p className="text-3xl font-bold text-[#b88d2b]">{pkg.price}<span className="text-sm"> ر.س</span></p>
                  <p className="text-sm text-muted-foreground mt-1">{pkg.duration} يوم</p>
                </div>
                <div className="mb-4">
                  <p className="text-xs text-muted-foreground mb-2">المميزات:</p>
                  <ul className="space-y-1">
                    {pkg.features?.map((feature, idx) => (
                      <li key={idx} className="text-sm flex items-start gap-2">
                        <span className="text-[#b88d2b]">✓</span>
                        <span>{feature}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                <Badge className={pkg.type === 'مميز' ? 'bg-[#b88d2b]' : 'bg-gray-400'}>
                  {pkg.type}
                </Badge>
              </Card>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

