      console.log(`✅ Backup deleted: ${req.params.id}`);
      res.json({ ok: true, message: "تم حذف النسخة الاحتياطية" });
    } catch (err: any) {
      console.error("Delete backup error:", err?.message);
      res.status(500).json({ error: "Failed to delete backup" });
    }
  });

